import React from 'react';
import { Link } from 'react-router-dom';
import '../assets/styles.css';
import '../assets/home-dark.css';
import '../assets/server-theme.css';

import logoNuevo from '../assets/img/logonuevo.png';
import UserMenu from '../components/UserMenu.jsx';

const DISCORD_URL = 'https://discord.rustaco.site';
const STORE_URL = 'https://store.rustaco.co';
const SUPPORT_URL = 'https://discord.rustaco.site';
const SERVER_NAME = 'Rustaco.co - Main 2x';

// ─── EDITA AQUÍ LAS REGLAS ─────────────────────────────────────────────────
// Cada sección agrupa reglas relacionadas. La numeración es continua y se
// genera automáticamente, así que puedes reordenar o añadir reglas libremente.
const RULE_SECTIONS = [
  {
    section: 'Cuentas y acceso',
    icon: 'bi-person-badge',
    rules: [
      {
        title: 'Una cuenta por jugador',
        text: 'Solo puedes jugar con tu cuenta principal de Steam. El uso de cuentas alternativas (alts) para espiar, ocupar slots, falsear estadísticas o sortear sanciones está prohibido y conlleva el ban de todas las cuentas asociadas.',
      },
      {
        title: 'Evasión de sanciones',
        text: 'Intentar evadir un ban mediante VPN, nuevas cuentas o suplantación reinicia y prolonga la sanción de forma permanente. La única vía válida para revisar un ban es la apelación por ticket.',
      },
      {
        title: 'Historial de bans del juego',
        text: 'No se permite el acceso a cuentas con un VAC o Game Ban de Rust de antigüedad inferior a 365 días. Convivir, compartir base o aliarse con un jugador baneado del servidor también es sancionable.',
      },
      {
        title: 'Cuenta verificable',
        text: 'El staff puede solicitar que tu perfil de Steam sea público durante una investigación. Negarse a colaborar con una investigación activa puede derivar en restricción temporal.',
      },
    ],
  },
  {
    section: 'Trampas y software de terceros',
    icon: 'bi-shield-shaded',
    rules: [
      {
        title: 'Cero tolerancia a las trampas',
        text: 'Cualquier software que otorgue ventaja injusta —aimbot, ESP/wallhack, spinbot, no-recoil, radar— resulta en ban permanente e irrevocable a la primera infracción, sin excepciones.',
      },
      {
        title: 'Scripts y macros',
        text: 'Están prohibidos los scripts y macros que automaticen acciones del juego, incluyendo macros de no-recoil, auto-farm, auto-clicker y combinaciones de teclas que ejecuten múltiples acciones con una sola pulsación.',
      },
      {
        title: 'Abuso de bugs y exploits',
        text: 'Aprovechar fallos del juego o de los plugins para obtener ventaja (duplicación de objetos, atravesar paredes, stacks ilegales, exploits de terreno) está prohibido. Reportar un exploit en lugar de abusarlo puede ser recompensado.',
      },
    ],
  },
  {
    section: 'Construcción y terreno',
    icon: 'bi-bricks',
    rules: [
      {
        title: 'Monumentos y zonas comunes',
        text: 'No se permite construir dentro de monumentos, bloquear puzzles, accesos a cuevas, vías de tren ni zonas de recolección de forma que impida el paso o el uso normal a otros jugadores.',
      },
      {
        title: 'Bloqueo de spawns',
        text: 'Queda prohibido sellar o bloquear puntos de aparición de la playa para impedir que jugadores nuevos entren al wipe.',
      },
      {
        title: 'Bases dentro del terreno',
        text: 'Está prohibido el uso de exploits de construcción que oculten loot dentro de rocas, terreno o estructuras inaccesibles por medios legítimos de raid.',
      },
      {
        title: 'Rendimiento del servidor',
        text: 'No se permiten estructuras o mecanismos diseñados para causar lag intencional (lag machines), incluyendo cantidades excesivas de entidades, agua o luces con el fin de degradar el rendimiento.',
      },
    ],
  },
  {
    section: 'Raideo y combate',
    icon: 'bi-fire',
    rules: [
      {
        title: 'Raid online y offline 24/7',
        text: 'El raideo está permitido en todo momento, tanto online como offline. Juega siempre asumiendo que tu base puede ser atacada en cualquier instante del wipe.',
      },
      {
        title: 'Sin griefing destructivo',
        text: 'Tras un raid puedes tomar el loot y la base. No se permite el griefing puro: sellar a un jugador dentro de su base sin acceso, tapar por completo una base con muros externos sin intención de raid, o destruir loot únicamente para perjudicar.',
      },
      {
        title: 'Sin límite de grupo ni alianzas',
        text: 'En Rustaco.co - Main 2x no hay límite de grupo: puedes jugar, farmear y raidear con cuantos jugadores quieras, y las alianzas entre grupos están permitidas. El staff solo intervendrá ante abusos que arruinen el wipe para el resto del servidor.',
      },
    ],
  },
  {
    section: 'Conducta y comunicación',
    icon: 'bi-chat-dots',
    rules: [
